// Agent için veri hazırlama - Developer Tool formatında
const item = $input.first().json;

const userQuery = item.chatInput;
const fileContext = item.upload_file_context || '';

// URL'leri kullanıcı sorgusundan ayıkla
const urlRegex = /https?:\/\/[^\s]+/g;
const sources = userQuery.match(urlRegex) || [];

// URL temizleyici - sadece query'den URL'leri çıkar

const cleanedQuery = item.chatInput.replace(urlRegex, '').trim();

// n8n dokümanları URL'sini varsayılan olarak ekle
if (!sources.includes('https://docs.n8n.io/glossary/')) {
  sources.push('https://docs.n8n.io/glossary/');
}

let addedFileContext = cleanedQuery

// Dosya içeriği varsa, query'yi zenginleştir
if (fileContext && fileContext.trim() !== '') {
  addedFileContext += `\n\n--- UPLOADED FILE CONTEXT ---\n${fileContext}`;
}

// Agent ve Developer Tool için veri hazırla
return {
  ...item,
  cleaned_query: cleanedQuery,
  added_file_context: addedFileContext, 
  upload_file_context: fileContext,
  sources: sources
};
